-- PREPARED CONTRACT ONLY. DO NOT APPLY FROM THIS CHECKPOINT.
-- Requires the existing ambulatory assessment, plans, medical orders, documents, contacts, treatment, qualification and permission contracts.
-- This contract never derives an order, advance-directive validity, intervention, effect, death confirmation, guardianship, specialist approval or cultural measure.
begin;
create schema if not exists care_private;
create table if not exists public.palliative_special_care_paths(
 id uuid primary key,tenant_id uuid not null references public.tenants(id),client_id uuid not null references public.clients(id),assessment_id uuid not null references public.care_assessments(id) on delete restrict,
 root_id uuid not null,previous_id uuid references public.palliative_special_care_paths(id) on delete restrict,revision integer not null check(revision>0),status text not null check(status in('draft','review_requested','returned','released','corrected')),
 entry jsonb not null,reason text not null default '',recorded_by uuid not null references public.profiles(id),recorded_at timestamptz not null default clock_timestamp(),fingerprint text not null,unique(root_id,revision)
);
create index if not exists palliative_special_care_path_page on public.palliative_special_care_paths(tenant_id,client_id,assessment_id,recorded_at desc,id desc);
create table if not exists care_private.palliative_special_care_path_receipts(
 tenant_id uuid not null,request_id uuid not null,client_id uuid not null,assessment_id uuid not null,actor_id uuid not null,packet jsonb not null,path_id uuid not null references public.palliative_special_care_paths(id),created_at timestamptz not null default clock_timestamp(),primary key(tenant_id,request_id)
);
create or replace function care_private.reject_palliative_special_original_change() returns trigger language plpgsql security definer set search_path='' as $$begin raise exception 'Palliative und besondere Originale und Quittungen sind append-only.' using errcode='42501';end$$;
revoke all on function care_private.reject_palliative_special_original_change() from public,anon,authenticated;
drop trigger if exists protect_palliative_special_care_path_original on public.palliative_special_care_paths;
create trigger protect_palliative_special_care_path_original before update or delete on public.palliative_special_care_paths for each row execute function care_private.reject_palliative_special_original_change();
drop trigger if exists protect_palliative_special_care_receipt on care_private.palliative_special_care_path_receipts;
create trigger protect_palliative_special_care_receipt before update or delete on care_private.palliative_special_care_path_receipts for each row execute function care_private.reject_palliative_special_original_change();
alter table public.palliative_special_care_paths enable row level security;
alter table care_private.palliative_special_care_path_receipts enable row level security;
revoke all on public.palliative_special_care_paths,care_private.palliative_special_care_path_receipts from public,anon,authenticated;
grant select on public.palliative_special_care_paths to authenticated;
drop policy if exists palliative_special_care_path_read on public.palliative_special_care_paths;
create policy palliative_special_care_path_read on public.palliative_special_care_paths for select to authenticated using(tenant_id=public.current_tenant_id() and public.is_active_pfleger_client(client_id) and public.has_permission('pflege.plans.view') and public.has_permission('pflege.orders.view') and public.has_permission('office.documents.view') and public.has_permission('office.clients.view_sensitive'));

create or replace function care_private.assert_palliative_special_path_actor(p_tenant uuid,p_actor uuid,p_manage boolean default false,p_release boolean default false)
returns void language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null or p_tenant is distinct from public.current_tenant_id() or p_actor is distinct from public.resolve_current_profile_id()
 or not exists(select 1 from public.profiles p where p.id=p_actor and p.tenant_id=p_tenant and p.is_active)
 or public.has_permission('pflege.plans.view') is not true or public.has_permission('pflege.orders.view') is not true or public.has_permission('office.documents.view') is not true or public.has_permission('office.clients.view_sensitive') is not true
 or (p_manage and (public.has_permission('pflege.assessments.manage') is not true or public.has_permission('pflege.orders.manage') is not true))
 or (p_release and public.has_permission('pflege.audit.view') is not true)
 then raise exception 'Aktuelle Sitzung, Person, Mandant oder Palliativ-/Spezialversorgungsrecht fehlt.' using errcode='42501';end if;
end$$;
revoke all on function care_private.assert_palliative_special_path_actor(uuid,uuid,boolean,boolean) from public,anon,authenticated;

create or replace function care_private.palliative_special_ref(p_id uuid,p_revision integer,p_recorded timestamptz,p_tenant uuid,p_client uuid,p_assessment uuid,p_payload jsonb)
returns jsonb language sql immutable strict set search_path='' as $$select jsonb_build_object('id',p_id,'revision',p_revision,'recordedAt',to_char(p_recorded at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'fingerprint','sha256:'||encode(extensions.digest(convert_to(p_payload::text,'UTF8'),'sha256'),'hex'),'tenantId',p_tenant,'clientId',p_client,'assessmentId',p_assessment,'payload',p_payload)$$;
revoke all on function care_private.palliative_special_ref(uuid,integer,timestamptz,uuid,uuid,uuid,jsonb) from public,anon,authenticated;

create or replace function care_private.palliative_special_path_original(p_path uuid) returns jsonb language sql security definer set search_path='' stable as $$
with head as(select * from public.palliative_special_care_paths where id=p_path),history as(select h.* from public.palliative_special_care_paths h join head x on x.root_id=h.root_id where h.revision<=x.revision order by h.revision),items as(select jsonb_agg(jsonb_build_object('id',id,'revision',revision,'previousId',previous_id,'recordedAt',to_char(recorded_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'recordedBy',recorded_by,'reason',reason,'status',status,'entry',entry,'fingerprint',fingerprint) order by revision) value from history)
select jsonb_build_object('id',h.id,'tenantId',h.tenant_id,'clientId',h.client_id,'assessmentId',h.assessment_id,'rootId',h.root_id,'headId',h.id,'revision',h.revision,'status',h.status,'entry',h.entry,'history',i.value) from head h cross join items i$$;
revoke all on function care_private.palliative_special_path_original(uuid) from public,anon,authenticated;

create or replace function care_private.read_palliative_special_care_path_context(p_tenant_id uuid,p_client_id uuid,p_assessment_id uuid,p_actor_profile_id uuid)
returns jsonb language plpgsql security definer set search_path='' stable as $$declare a public.care_assessments%rowtype;result jsonb;begin
 perform care_private.assert_palliative_special_path_actor(p_tenant_id,p_actor_profile_id,false,false);
 select * into a from public.care_assessments x where x.id=p_assessment_id and x.tenant_id=p_tenant_id and x.subject_type='client' and x.subject_id=p_client_id;
 if a.id is null or public.is_active_pfleger_client(p_client_id) is not true then raise exception 'Eigenes Assessment oder aktiver Pflegefall fehlt.' using errcode='42501';end if;
 select jsonb_build_object(
 'assessment',jsonb_build_array(care_private.palliative_special_ref(a.id,coalesce(a.draft_revision,0),a.updated_at,p_tenant_id,p_client_id,a.id,to_jsonb(a)-'tenant_id')),
 'plans',coalesce((select jsonb_agg(care_private.palliative_special_ref(p.id,1,p.updated_at,p_tenant_id,p_client_id,a.id,to_jsonb(p)-'tenant_id'-'client_id') order by p.id) from public.care_plans p where p.tenant_id=p_tenant_id and p.client_id=p_client_id),'[]'::jsonb),
 'documents',coalesce((select jsonb_agg(care_private.palliative_special_ref(d.id,1,d.updated_at,p_tenant_id,p_client_id,a.id,jsonb_build_object('title',d.title,'file_name',d.file_name,'category',d.category,'status',d.status,'sensitivity',d.sensitivity,'valid_until',d.valid_until)) order by d.id) from public.client_documents d where d.tenant_id=p_tenant_id and d.client_id=p_client_id),'[]'::jsonb),
 'orders',coalesce((select jsonb_agg(care_private.palliative_special_ref(o.id,1,o.updated_at,p_tenant_id,p_client_id,a.id,jsonb_build_object('title',o.title,'order_type',o.order_type,'status',o.status,'valid_from',o.valid_from,'valid_until',o.valid_until,'qualification_requirement',o.qualification_requirement)) order by o.id) from public.care_medical_orders o where o.tenant_id=p_tenant_id and o.client_id=p_client_id),'[]'::jsonb),
 'observations',coalesce((select jsonb_agg(care_private.palliative_special_ref(e.id,0,e.created_at,p_tenant_id,p_client_id,a.id,to_jsonb(e)-'tenant_id'-'assessment_id') order by e.id) from public.care_assessment_events e where e.tenant_id=p_tenant_id and e.assessment_id=a.id),'[]'::jsonb),
 'interventions',coalesce((select jsonb_agg(care_private.palliative_special_ref(e.id,1,e.created_at,p_tenant_id,p_client_id,a.id,to_jsonb(e)-'tenant_id'-'client_id') order by e.id) from public.clinical_treatment_executions e where e.tenant_id=p_tenant_id and e.client_id=p_client_id),'[]'::jsonb),
 'contacts',coalesce((select jsonb_agg(care_private.palliative_special_ref(c.id,1,c.created_at,p_tenant_id,p_client_id,a.id,to_jsonb(c)-'tenant_id'-'client_id') order by c.id) from public.client_contacts c where c.tenant_id=p_tenant_id and c.client_id=p_client_id),'[]'::jsonb),
 'confirmations',coalesce((select jsonb_agg(care_private.palliative_special_ref(d.id,1,d.updated_at,p_tenant_id,p_client_id,a.id,jsonb_build_object('title',d.title,'category',d.category,'status',d.status,'valid_until',d.valid_until,'medical_validity_not_inferred',true)) order by d.id) from public.client_documents d where d.tenant_id=p_tenant_id and d.client_id=p_client_id and d.category='arztbrief'),'[]'::jsonb),
 'guardianships',coalesce((select jsonb_agg(care_private.palliative_special_ref(c.id,1,c.created_at,p_tenant_id,p_client_id,a.id,jsonb_build_object('name',c.name,'relationship',c.relationship,'source_only_not_legal_confirmation',true)) order by c.id) from public.client_contacts c where c.tenant_id=p_tenant_id and c.client_id=p_client_id),'[]'::jsonb),
 'qualifications',coalesce((select jsonb_agg(care_private.palliative_special_ref(q.id,1,q.updated_at,p_tenant_id,p_client_id,a.id,jsonb_build_object('title',q.title,'qualification_type',q.qualification_type,'valid_until',q.valid_until,'status',q.status,'employee_id',q.employee_id)) order by q.id) from public.employee_qualifications q where q.tenant_id=p_tenant_id),'[]'::jsonb),
 'approvals',coalesce((select jsonb_agg(care_private.palliative_special_ref(o.id,1,o.updated_at,p_tenant_id,p_client_id,a.id,jsonb_build_object('title',o.title,'state',o.insurer_approval_status,'reference',o.insurer_approval_reference,'valid_until',o.valid_until,'specific_release_not_inferred',true)) order by o.id) from public.care_medical_orders o where o.tenant_id=p_tenant_id and o.client_id=p_client_id and o.insurer_approval_status<>'not_required'),'[]'::jsonb),
 'people',coalesce((select jsonb_agg(care_private.palliative_special_ref(p.id,1,coalesce(p.updated_at,p.created_at),p_tenant_id,p_client_id,a.id,jsonb_build_object('display_name',coalesce(nullif(p.display_name,''),p.email),'active',p.is_active)) order by p.id) from public.profiles p where p.tenant_id=p_tenant_id and p.is_active),'[]'::jsonb),
 'paths',coalesce((select jsonb_agg(care_private.palliative_special_ref(v.id,v.revision,v.recorded_at,p_tenant_id,p_client_id,a.id,jsonb_build_object('title',v.entry->>'title','status',v.status)) order by v.id) from public.palliative_special_care_paths v where v.tenant_id=p_tenant_id and v.client_id=p_client_id and v.assessment_id=a.id),'[]'::jsonb)
 ) into result;return result;
end$$;
revoke all on function care_private.read_palliative_special_care_path_context(uuid,uuid,uuid,uuid) from public,anon,authenticated;
create or replace function public.web_read_palliative_special_care_path_context(p_tenant_id uuid,p_client_id uuid,p_assessment_id uuid,p_actor_profile_id uuid) returns jsonb language sql security invoker set search_path='' as $$select care_private.read_palliative_special_care_path_context(p_tenant_id,p_client_id,p_assessment_id,p_actor_profile_id)$$;
revoke all on function public.web_read_palliative_special_care_path_context(uuid,uuid,uuid,uuid) from public,anon;
grant execute on function public.web_read_palliative_special_care_path_context(uuid,uuid,uuid,uuid) to authenticated;

create or replace function care_private.read_palliative_special_care_path_page(p_tenant_id uuid,p_client_id uuid,p_assessment_id uuid,p_actor_profile_id uuid,p_cursor_recorded_at timestamptz,p_cursor_id uuid,p_page_size integer) returns jsonb language plpgsql security definer set search_path='' stable as $$declare rows jsonb;last_at timestamptz;last_id uuid;begin
 perform care_private.assert_palliative_special_path_actor(p_tenant_id,p_actor_profile_id,false,false);if p_page_size not between 1 and 100 or public.is_active_pfleger_client(p_client_id) is not true then raise exception 'Ungültige Verlaufsauswahl.' using errcode='42501';end if;
 with heads as(select distinct on(root_id) * from public.palliative_special_care_paths where tenant_id=p_tenant_id and client_id=p_client_id and assessment_id=p_assessment_id order by root_id,revision desc),page as(select * from heads where p_cursor_recorded_at is null or (recorded_at,id)<(p_cursor_recorded_at,p_cursor_id) order by recorded_at desc,id desc limit p_page_size)
 select coalesce(jsonb_agg(care_private.palliative_special_path_original(id) order by recorded_at desc,id desc),'[]'::jsonb),(array_agg(recorded_at order by recorded_at desc,id desc))[count(*)],(array_agg(id order by recorded_at desc,id desc))[count(*)] into rows,last_at,last_id from page;
 return jsonb_build_object('rows',rows,'nextCursorRecordedAt',case when last_at is null then null else to_char(last_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') end,'nextCursorId',last_id);
end$$;
revoke all on function care_private.read_palliative_special_care_path_page(uuid,uuid,uuid,uuid,timestamptz,uuid,integer) from public,anon,authenticated;
create or replace function public.web_read_palliative_special_care_path_page(p_tenant_id uuid,p_client_id uuid,p_assessment_id uuid,p_actor_profile_id uuid,p_cursor_recorded_at timestamptz,p_cursor_id uuid,p_page_size integer) returns jsonb language sql security invoker set search_path='' as $$select care_private.read_palliative_special_care_path_page(p_tenant_id,p_client_id,p_assessment_id,p_actor_profile_id,p_cursor_recorded_at,p_cursor_id,p_page_size)$$;
revoke all on function public.web_read_palliative_special_care_path_page(uuid,uuid,uuid,uuid,timestamptz,uuid,integer) from public,anon;
grant execute on function public.web_read_palliative_special_care_path_page(uuid,uuid,uuid,uuid,timestamptz,uuid,integer) to authenticated;

create or replace function care_private.commit_palliative_special_care_path_packet(p_packet jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare tenant uuid:=(p_packet->>'tenantId')::uuid;client uuid:=(p_packet->>'clientId')::uuid;assessment uuid:=(p_packet->>'assessmentId')::uuid;actor uuid:=(p_packet->>'actorId')::uuid;request uuid:=(p_packet->>'requestId')::uuid;entry jsonb:=p_packet->'entry';state text:=entry->>'status';prior care_private.palliative_special_care_path_receipts%rowtype;head public.palliative_special_care_paths%rowtype;next_id uuid:=gen_random_uuid();next_root uuid;next_revision integer;fingerprint text;current_sources jsonb;release_action boolean:=state in('released','corrected');
begin
 if jsonb_typeof(p_packet) is distinct from 'object' or length(p_packet::text)>3000000 or p_packet->>'schemaVersion'<>'1' or p_packet->>'action' not in('create','revise') then raise exception 'Ungültiges Palliativ- und Spezialversorgungs-Gesamtpaket.' using errcode='23514';end if;
 perform care_private.assert_palliative_special_path_actor(tenant,actor,true,release_action);perform pg_advisory_xact_lock(hashtextextended(tenant::text||':'||client::text||':'||assessment::text,0));
 if not exists(select 1 from public.care_assessments a where a.id=assessment and a.tenant_id=tenant and a.subject_type='client' and a.subject_id=client) or public.is_active_pfleger_client(client) is not true then raise exception 'Assessment oder Pflegefall ist nicht aktuell zugänglich.' using errcode='42501';end if;
 select * into prior from care_private.palliative_special_care_path_receipts r where r.tenant_id=tenant and r.request_id=request for update;if prior.request_id is not null then if prior.client_id<>client or prior.assessment_id<>assessment or prior.actor_id<>actor or prior.packet<>p_packet then raise exception 'Anfrageidentität wurde mit anderen Originalen verwendet.' using errcode='23514';end if;return jsonb_build_object('requestId',request,'packet',prior.packet,'original',care_private.palliative_special_path_original(prior.path_id));end if;
 if entry->>'tenantId' is distinct from tenant::text or entry->>'clientId' is distinct from client::text or entry->>'assessmentId' is distinct from assessment::text or state not in('draft','review_requested','returned','released','corrected') then raise exception 'Palliative und besondere Akten- oder Statusbindung fehlt.' using errcode='23514';end if;
 if length(btrim(coalesce(entry#>>'{goals,personWishes}','')))<3 or length(btrim(coalesce(entry#>>'{goals,careGoal}','')))<3 or length(btrim(coalesce(entry#>>'{goals,involvedPeople}','')))<3 or length(btrim(coalesce(entry#>>'{goals,informationSource}','')))<3 or length(btrim(coalesce(entry#>>'{goals,orderBoundary}','')))<8 or nullif(entry#>>'{goals,reviewedAt}','') is null or nullif(entry#>>'{goals,medicalOrderId}','') is null then raise exception 'Personenwünsche, Versorgungsziel, Beteiligte, Quelle, Prüfzeitpunkt und getrennte ärztliche Anordnung sind unvollständig.' using errcode='23514';end if;
 if nullif(entry#>>'{advanceDirective,documentId}','') is null or length(btrim(coalesce(entry#>>'{advanceDirective,documentVersion}','')))<3 or nullif(entry#>>'{advanceDirective,documentRecordedAt}','') is null or length(btrim(coalesce(entry#>>'{advanceDirective,reviewStatus}','')))<3 or nullif(entry#>>'{advanceDirective,reviewedBy}','') is null or nullif(entry#>>'{advanceDirective,reviewedAt}','') is null or length(btrim(coalesce(entry#>>'{advanceDirective,contactPerson}','')))<3 or length(btrim(coalesce(entry#>>'{advanceDirective,accessInstructions}','')))<3 or length(btrim(coalesce(entry#>>'{advanceDirective,outdatedVersionNote}','')))<3 then raise exception 'Patientenverfügung benötigt Original, Fassung, Prüfung, Kontakt, Zugriff und Kennzeichnung alter Fassungen.' using errcode='23514';end if;
 if length(btrim(coalesce(entry#>>'{symptoms,pain}','')))<3 or length(btrim(coalesce(entry#>>'{symptoms,dyspnea}','')))<3 or length(btrim(coalesce(entry#>>'{symptoms,nausea}','')))<3 or length(btrim(coalesce(entry#>>'{symptoms,burden}','')))<3 or nullif(entry#>>'{symptoms,observedAt}','') is null or length(btrim(coalesce(entry#>>'{symptoms,intervention}','')))<3 or nullif(entry#>>'{symptoms,interventionAt}','') is null or length(btrim(coalesce(entry#>>'{symptoms,effectControl}','')))<3 or nullif(entry#>>'{symptoms,controlledAt}','') is null or nullif(entry#>>'{symptoms,documentedBy}','') is null then raise exception 'Symptome, Beobachtung, tatsächliche Maßnahme und Wirkungskontrolle müssen zeitlich und personell getrennt vollständig sein.' using errcode='23514';end if;
 if length(btrim(coalesce(entry#>>'{dyingPhase,observation}','')))<3 or length(btrim(coalesce(entry#>>'{dyingPhase,support}','')))<3 or length(btrim(coalesce(entry#>>'{dyingPhase,contactPerson}','')))<3 or length(btrim(coalesce(entry#>>'{dyingPhase,contactAgreement}','')))<3 or length(btrim(coalesce(entry#>>'{dyingPhase,contactAttempt}','')))<3 or nullif(entry#>>'{dyingPhase,reachedAt}','') is null or length(btrim(coalesce(entry#>>'{dyingPhase,handover}','')))<3 then raise exception 'Sterbephasenbeobachtung, Unterstützung, Kontaktvereinbarung, tatsächlicher Versuch und Übergabe sind unvollständig.' using errcode='23514';end if;
 if nullif(entry#>>'{deathClosure,observedAt}','') is null or nullif(entry#>>'{deathClosure,observedBy}','') is null or nullif(entry#>>'{deathClosure,medicalConfirmationId}','') is null or nullif(entry#>>'{deathClosure,confirmedAt}','') is null or nullif(entry#>>'{deathClosure,confirmedBy}','') is null or length(btrim(coalesce(entry#>>'{deathClosure,notifiedContacts}','')))<3 or length(btrim(coalesce(entry#>>'{deathClosure,materialReturn}','')))<3 or length(btrim(coalesce(entry#>>'{deathClosure,contractClosure}','')))<3 or nullif(entry#>>'{deathClosure,closedAt}','') is null then raise exception 'Beobachtung, medizinische Feststellungsquelle, Kontakte, Material- und Vertragsabschluss bleiben getrennt erforderlich.' using errcode='23514';end if;
 if entry#>>'{pediatric,subjectGroup}' not in('minor','adult') or length(btrim(coalesce(entry#>>'{pediatric,adultSchemaBoundary}','')))<8 then raise exception 'Alterskontext und Grenze zwischen Erwachsenen- und Kinderschemata fehlen.' using errcode='23514';end if;
 if entry#>>'{pediatric,subjectGroup}'='minor' and (nullif(entry#>>'{pediatric,guardianId}','') is null or length(btrim(coalesce(entry#>>'{pediatric,guardianBasis}','')))<3 or length(btrim(coalesce(entry#>>'{pediatric,developmentContext}','')))<3 or jsonb_typeof(entry#>'{pediatric,weightKg}') is distinct from 'number' or (entry#>>'{pediatric,weightKg}')::numeric<=0 or nullif(entry#>>'{pediatric,weightMeasuredAt}','') is null or length(btrim(coalesce(entry#>>'{pediatric,specificPlan}','')))<3) then raise exception 'Versorgung Minderjähriger benötigt Sorgeberechtigung, Entwicklungsbezug, aktuelles Gewicht und spezifischen Plan.' using errcode='23514';end if;
 if length(btrim(coalesce(entry#>>'{complexParticipation,communicationAids}','')))<3 or length(btrim(coalesce(entry#>>'{complexParticipation,assistant}','')))<3 or length(btrim(coalesce(entry#>>'{complexParticipation,resources}','')))<3 or length(btrim(coalesce(entry#>>'{complexParticipation,coordination}','')))<3 or length(btrim(coalesce(entry#>>'{complexParticipation,immediateHandover}','')))<3 then raise exception 'Kommunikationshilfen, Assistenz, Ressourcen, Koordination und Einsatzübergabe sind unvollständig.' using errcode='23514';end if;
 if length(btrim(coalesce(entry#>>'{specializedCare,profile}','')))<3 or nullif(entry#>>'{specializedCare,contractId}','') is null or nullif(entry#>>'{specializedCare,qualificationId}','') is null or length(btrim(coalesce(entry#>>'{specializedCare,evidence}','')))<3 or entry#>>'{specializedCare,verificationState}'<>'unverified' or length(btrim(coalesce(entry#>>'{specializedCare,verificationNote}','')))<8 then raise exception 'Spezialprofil muss bis zur eigenen Abnahme ungeprüft bleiben und Vertrag sowie Fachnachweis getrennt binden.' using errcode='23514';end if;
 if length(btrim(coalesce(entry#>>'{specialService,serviceOrder}','')))<3 or length(btrim(coalesce(entry#>>'{specialService,responsibility}','')))<3 or nullif(entry#>>'{specialService,qualificationId}','') is null or nullif(entry#>>'{specialService,approvalId}','') is null or length(btrim(coalesce(entry#>>'{specialService,contactPoint}','')))<3 or length(btrim(coalesce(entry#>>'{specialService,specificReleaseBoundary}','')))<8 then raise exception 'Gesonderte Spezialleistung benötigt Auftrag, Zuständigkeit, Fachnachweis, eigene Freigabequelle und Freigabegrenze.' using errcode='23514';end if;
 if length(btrim(coalesce(entry#>>'{culturalCare,wishes}','')))<3 or length(btrim(coalesce(entry#>>'{culturalCare,language}','')))<3 or length(btrim(coalesce(entry#>>'{culturalCare,interpreter}','')))<3 or length(btrim(coalesce(entry#>>'{culturalCare,religiousNeeds}','')))<3 or length(btrim(coalesce(entry#>>'{culturalCare,agreedHelp}','')))<3 or length(btrim(coalesce(entry#>>'{culturalCare,individualBasis}','')))<3 or length(btrim(coalesce(entry#>>'{culturalCare,stereotypeGuard}','')))<8 then raise exception 'Kultursensible Versorgung benötigt individuelle Wünsche, Sprache, Unterstützung, Vereinbarung, Quelle und Stereotypengrenze.' using errcode='23514';end if;
 if state='review_requested' and ((entry#>>'{review,requestedBy}')::uuid<>actor or nullif(entry#>>'{review,requestedAt}','') is null) then raise exception 'Prüfanfrage benötigt aktuelle Person und tatsächlichen Zeitpunkt.' using errcode='23514';end if;
 if state='returned' and ((entry#>>'{review,returnedBy}')::uuid<>actor or nullif(entry#>>'{review,returnedAt}','') is null or length(btrim(coalesce(entry#>>'{review,returnReason}','')))<10) then raise exception 'Rückgabe benötigt aktuelle Person, Zeitpunkt und Grund.' using errcode='23514';end if;
 if state='released' and ((entry#>>'{review,releasedBy}')::uuid<>actor or nullif(entry#>>'{review,releasedAt}','') is null or nullif(entry#>>'{review,requestedBy}','') is null or entry#>>'{review,requestedBy}'=actor::text) then raise exception 'Freigabe benötigt vorherige Prüfanfrage und getrennte aktuelle Freigabeperson.' using errcode='23514';end if;
 if state='corrected' and (nullif(entry#>>'{review,correctionTargetId}','') is null or length(btrim(coalesce(entry#>>'{review,correctionReason}','')))<10 or not exists(select 1 from public.palliative_special_care_paths v where v.id=(entry#>>'{review,correctionTargetId}')::uuid and v.tenant_id=tenant and v.client_id=client and v.assessment_id=assessment)) then raise exception 'Append-only-Korrektur benötigt historisches Ziel und konkreten Grund.' using errcode='23514';end if;
 current_sources:=care_private.read_palliative_special_care_path_context(tenant,client,assessment,actor);if current_sources is distinct from p_packet->'sources' then raise exception 'Palliativ- und Spezialversorgungs-Originalquellen wurden verändert. Vollständig neu laden.' using errcode='40001';end if;
 if not exists(select 1 from jsonb_array_elements(current_sources->'orders') x where x->>'id'=entry#>>'{goals,medicalOrderId}') or not exists(select 1 from jsonb_array_elements(current_sources->'documents') x where x->>'id'=entry#>>'{advanceDirective,documentId}') or not exists(select 1 from jsonb_array_elements(current_sources->'documents') x where x->>'id'=entry#>>'{specializedCare,contractId}') then raise exception 'Anordnung, Verfügung oder Spezialvertragsoriginal fehlt im aktuellen vollständigen Originalbestand.' using errcode='23514';end if;
 if not exists(select 1 from jsonb_array_elements(current_sources->'people') x where x->>'id'=entry#>>'{advanceDirective,reviewedBy}') or not exists(select 1 from jsonb_array_elements(current_sources->'people') x where x->>'id'=entry#>>'{symptoms,documentedBy}') or not exists(select 1 from jsonb_array_elements(current_sources->'people') x where x->>'id'=entry#>>'{deathClosure,observedBy}') or not exists(select 1 from jsonb_array_elements(current_sources->'people') x where x->>'id'=entry#>>'{deathClosure,confirmedBy}') then raise exception 'Eine beteiligte Person fehlt im aktuellen vollständigen Originalbestand.' using errcode='23514';end if;
 if not exists(select 1 from jsonb_array_elements(current_sources->'confirmations') x where x->>'id'=entry#>>'{deathClosure,medicalConfirmationId}') then raise exception 'Die medizinische Feststellungsquelle fehlt im aktuellen vollständigen Originalbestand.' using errcode='23514';end if;
 if entry#>>'{pediatric,subjectGroup}'='minor' and not exists(select 1 from jsonb_array_elements(current_sources->'guardianships') x where x->>'id'=entry#>>'{pediatric,guardianId}') then raise exception 'Die Sorgeberechtigungsquelle fehlt im aktuellen vollständigen Originalbestand.' using errcode='23514';end if;
 if not exists(select 1 from jsonb_array_elements(current_sources->'qualifications') x where x->>'id'=entry#>>'{specializedCare,qualificationId}') or not exists(select 1 from jsonb_array_elements(current_sources->'qualifications') x where x->>'id'=entry#>>'{specialService,qualificationId}') or not exists(select 1 from jsonb_array_elements(current_sources->'approvals') x where x->>'id'=entry#>>'{specialService,approvalId}') then raise exception 'Fachnachweis oder spezifische Freigabequelle fehlt im aktuellen vollständigen Originalbestand.' using errcode='23514';end if;
 if p_packet->>'action'='create' then if p_packet->'original'<>'null'::jsonb or p_packet->'expectedHeadId'<>'null'::jsonb or (p_packet->>'expectedRevision')::integer<>0 or coalesce(p_packet->>'reason','')<>'' then raise exception 'Neuanlage enthält historischen Kopf.' using errcode='23514';end if;next_root:=next_id;next_revision:=1;
 else select * into head from public.palliative_special_care_paths v where v.id=(p_packet->>'expectedHeadId')::uuid and v.tenant_id=tenant and v.client_id=client and v.assessment_id=assessment for update;if head.id is null or exists(select 1 from public.palliative_special_care_paths newer where newer.root_id=head.root_id and newer.revision>head.revision) or head.revision<>(p_packet->>'expectedRevision')::integer or care_private.palliative_special_path_original(head.id) is distinct from p_packet->'original' or length(btrim(coalesce(p_packet->>'reason','')))<10 or head.entry=entry then raise exception 'Palliative und besonderer CAS-Kopf, Originalhistorie oder Fortschreibungsgrund wurde verändert.' using errcode='40001';end if;next_root:=head.root_id;next_revision:=head.revision+1;end if;
 fingerprint:='sha256:'||encode(extensions.digest(convert_to(entry::text,'UTF8'),'sha256'),'hex');insert into public.palliative_special_care_paths(id,tenant_id,client_id,assessment_id,root_id,previous_id,revision,status,entry,reason,recorded_by,fingerprint) values(next_id,tenant,client,assessment,next_root,head.id,next_revision,state,entry,coalesce(p_packet->>'reason',''),actor,fingerprint);insert into care_private.palliative_special_care_path_receipts(tenant_id,request_id,client_id,assessment_id,actor_id,packet,path_id) values(tenant,request,client,assessment,actor,p_packet,next_id);return jsonb_build_object('requestId',request,'packet',p_packet,'original',care_private.palliative_special_path_original(next_id));
end$$;
revoke all on function care_private.commit_palliative_special_care_path_packet(jsonb) from public,anon,authenticated;
create or replace function public.web_commit_palliative_special_care_path_packet(p_packet jsonb) returns jsonb language sql security invoker set search_path='' as $$select care_private.commit_palliative_special_care_path_packet(p_packet)$$;
revoke all on function public.web_commit_palliative_special_care_path_packet(jsonb) from public,anon;
grant execute on function public.web_commit_palliative_special_care_path_packet(jsonb) to authenticated;

create or replace function care_private.confirm_palliative_special_care_path_packet(p_tenant_id uuid,p_client_id uuid,p_assessment_id uuid,p_actor_profile_id uuid,p_request_id uuid,p_packet jsonb) returns jsonb language plpgsql security definer set search_path='' stable as $$declare r care_private.palliative_special_care_path_receipts%rowtype;begin perform care_private.assert_palliative_special_path_actor(p_tenant_id,p_actor_profile_id,false,false);select * into r from care_private.palliative_special_care_path_receipts x where x.tenant_id=p_tenant_id and x.request_id=p_request_id;if r.request_id is null or r.client_id<>p_client_id or r.assessment_id<>p_assessment_id or r.actor_id<>p_actor_profile_id or r.packet<>p_packet then return null;end if;return jsonb_build_object('requestId',p_request_id,'packet',r.packet,'original',care_private.palliative_special_path_original(r.path_id));end$$;
revoke all on function care_private.confirm_palliative_special_care_path_packet(uuid,uuid,uuid,uuid,uuid,jsonb) from public,anon,authenticated;
create or replace function public.web_confirm_palliative_special_care_path_packet(p_tenant_id uuid,p_client_id uuid,p_assessment_id uuid,p_actor_profile_id uuid,p_request_id uuid,p_packet jsonb) returns jsonb language sql security invoker set search_path='' as $$select care_private.confirm_palliative_special_care_path_packet(p_tenant_id,p_client_id,p_assessment_id,p_actor_profile_id,p_request_id,p_packet)$$;
revoke all on function public.web_confirm_palliative_special_care_path_packet(uuid,uuid,uuid,uuid,uuid,jsonb) from public,anon;
grant execute on function public.web_confirm_palliative_special_care_path_packet(uuid,uuid,uuid,uuid,uuid,jsonb) to authenticated;
commit;

